'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let lang=localStorage.getItem('bd-language')||'en';
const T=(en,ar)=>lang==='ar'?ar:en;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=x=>{try{const u=new URL(x);return ['http:','https:'].includes(u.protocol)?esc(u.href):''}catch{return ''}};
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const num=x=>new Intl.NumberFormat(lang==='ar'?'ar-SA':'en-GB',{maximumFractionDigits:0}).format(x);
let state={records:[],audit:[]},route='dashboard',query='',filters={},page=1,sortDir=1,selectedKind='suppliers',reportText='',reportTitle='',researchResult=null,busy=false;
const rows=k=>state.records.filter(r=>r.kind===k);
const get=id=>state.records.find(r=>r.id===id);
const name=id=>get(id)?.name||'';
const sectors=['Oil & Gas','Mining & Metals','Renewables & Power','Industrial & Water'];
const stages=['Identified','Qualified','Technical review','Proposal','Negotiation','Won','Lost','On hold'];
const taskNames=[['supplier','Supplier screening','فحص الموردين'],['project','Project intelligence','بحث المشاريع'],['partner','Partner assessment','تقييم الشركاء'],['meeting','Meeting preparation','التحضير للاجتماع'],['report','Management report','تقرير إداري']];
const templates={supplier:'Assess products, Saudi presence, existing agent or JV, technical approvals, source dates, evidence gaps, and recommended verification questions.',project:'Identify the project owner, EPC, scope, location, award status, timelines, relevant packages and verified sources. Separate announced dates from estimates.',partner:'Assess fit with customer needs, Saudi channel conflicts, delivery capabilities, localisation potential, evidence gaps and practical next steps.',meeting:'Prepare a concise meeting brief, five useful questions, discussion objectives, evidence needed and proposed actions. Do not invent previous agreements.',report:'Prepare a concise management report: progress, opportunities, risks, overdue actions, decisions required and next steps. Use supplied facts and cite sources.'};
const nav=[['dashboard','◫','Overview','نظرة عامة'],['suppliers','▦','Supplier intelligence','الموردون'],['opportunities','↗','Opportunities','الفرص'],['accounts','▤','Accounts & contacts','العملاء والاتصالات'],['actions','✓','Actions','المتابعات'],['meetings','▣','Meetings','الاجتماعات'],['sources','⊕','Sources & inputs','المصادر والمدخلات'],['research','⌕','Research workspace','مساحة البحث'],['reports','▥','Reports','التقارير'],['settings','⚙','Settings & backup','الإعدادات والنسخ']];
function toast(s,error=false){const e=$('#toast');e.textContent=s;e.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.className='',6500)}
function apiMessage(e){
 const labels={
  credit_balance_exhausted:T('Your API credit balance is exhausted. Check API billing.','نفد رصيد حساب OpenAI API. راجع الفوترة ورصيد API.'),
  organization_spend_limit_exceeded:T('Your organization API spend limit was reached. Review its limits.','وصلت المؤسسة إلى حد الإنفاق على API. راجع حدود المؤسسة.'),
  project_spend_limit_exceeded:T('Your project API spend limit was reached. Review its limits.','وصل المشروع إلى حد الإنفاق على API. راجع حدود المشروع.'),
  organization_usage_limit_exceeded:T('Your organization API usage limit was reached. Review its limits.','وصلت المؤسسة إلى حد الاستخدام المعتمد لـ API. راجع حدود المؤسسة.'),
  insufficient_quota:T('API quota is unavailable. Check API billing and limits.','حصة API غير متاحة. راجع الفوترة وحدود الاستخدام.'),
  rate_limit_exceeded:T('Too many API requests or tokens. Wait before trying again.','تجاوزت حد الطلبات أو الرموز خلال فترة قصيرة. انتظر ثم أعد المحاولة.'),
  rate_limit_error:T('Too many API requests or tokens. Wait before trying again.','تجاوزت حد الطلبات أو الرموز خلال فترة قصيرة. انتظر ثم أعد المحاولة.'),
  slow_down:T('OpenAI asked to slow the request rate. Wait before trying again.','طلبت OpenAI خفض سرعة الطلبات. انتظر ثم أعد المحاولة.')
 };
 const message=labels[e.error_code]||e.error||T('Request failed.','تعذر إكمال الطلب.');
 const seconds=Number(e.retry_after);
 return message+(seconds>0&&['rate_limit_exceeded','rate_limit_error','slow_down'].includes(e.error_code)?' '+T(`Wait at least ${seconds} seconds.`,`انتظر ${seconds} ثانية على الأقل.`):'');
}
async function api(path,data,blob=false){const options={headers:{'X-BD-Client':'1'}};if(data!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.headers['X-BD-Token']=state.token;options.body=JSON.stringify(data)}const r=await fetch('/api/'+path,options);if(!r.ok){const e=await r.json().catch(()=>({error:r.statusText}));throw Error(apiMessage(e))}return blob?r.blob():r.json()}

async function refresh(){state=await api('state')}
function download(blob,filename){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function options(values,current,empty){return (empty!==undefined?`<option value="">${esc(empty)}</option>`:'')+values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${String(current)===String(id)?'selected':''}>${esc(label)}</option>`}).join('')}
function badge(value){const labels={no:T('No presence found','لم يُعثر على حضور'),yes:T('Presence found','حضور موثّق بالمرجع'),maybe:T('Unconfirmed','غير مؤكد'),Open:T('Open','مفتوح'),Done:T('Done','مكتمل')};return `<span class="badge ${esc(['no','yes','maybe'].includes(value)?value:'')}">${esc(labels[value]||value||'—')}</span>`}
function empty(title,text,kind){return `<div class="empty"><h2>${title}</h2><p>${text}</p>${kind?`<button class="primary" data-new="${kind}">${T('Add first record','إضافة أول سجل')}</button>`:''}</div>`}
function head(title,sub,extra=''){return `<div class="page-head"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${extra}</div>`}
function navigate(r){route=r;query='';filters={};page=1;render()}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt=""><div><strong>BD Workspace</strong><small>${T('Personal edition','نسخة شخصية')}</small></div></div><div class="nav-caption">${T('Your workspace','مساحة العمل')}</div><nav aria-label="${T('Main navigation','القائمة الرئيسية')}">${nav.map(([id,icon,en,ar])=>`<button data-nav="${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${T(en,ar)}</button>`).join('')}</nav><div class="sidebar-footer">${T('Saudi Arabia · BD desk','السعودية · تطوير الأعمال')}<br>${T('Saved on this computer','محفوظ على هذا الجهاز')}<br>v2.0.3 · Local</div></aside><div><header class="topbar"><div class="topbar-title">${T('Research. Qualify. Follow through.','ابحث، قيّم، وتابع التنفيذ.')}</div><div class="top-actions"><span class="tag">${T('Local workspace','مساحة عمل محلية')}</span><button class="small" id="language">${lang==='en'?'العربية':'English'}</button><button class="small" id="reload">${T('Refresh','تحديث')}</button></div></header><main class="main" id="main">${pageContent()}</main></div></div>`;wire();}
function pageContent(){if(route==='dashboard')return overview();if(route==='sources')return sourcePage();if(route==='research')return researchPage();if(route==='reports')return reportsPage();if(route==='settings')return settingsPage();return tablePage()}
function overdue(r){return r.due&&r.due<day()&&r.status!=='Done'}
function overview(){const suppliers=rows('suppliers'),opps=rows('opportunities'),open=opps.filter(r=>!['Won','Lost'].includes(r.stage)),due=rows('actions').filter(overdue),short=suppliers.filter(r=>r.shortlisted);const totals={};open.forEach(r=>{if(r.value!==''&&r.value!=null){const c=r.currency||'SAR';totals[c]=(totals[c]||0)+Number(r.value)}});return head(T('Your BD overview','نظرة على أعمالك'),T('A clear view of research, pipeline and next actions.','نظرة واضحة على الأبحاث والفرص والخطوات القادمة.'),`<button class="primary" data-new="opportunities">+ ${T('New opportunity','فرصة جديدة')}</button>`)+`<div class="kpis">${[[suppliers.length,T('Companies in directory','الشركات بالدليل'),T('Imported research + your additions','البحث المستورد وإضافاتك')],[open.length,T('Active opportunities','الفرص النشطة'),Object.entries(totals).map(([c,v])=>`${c} ${num(v)}`).join(' · ')||T('Values not yet entered','لم تُدخل القيم بعد')],[due.length,T('Overdue actions','متابعات متأخرة'),T('Open actions past their due date','إجراءات مفتوحة تجاوزت موعدها')],[short.length,T('Shortlisted suppliers','الموردون بالقائمة المختصرة'),T('Selected for further assessment','مختارون لمزيد من التقييم')]].map(([v,l,d])=>`<div class="kpi"><div class="label">${l}</div><div class="number">${num(v)}</div><div class="detail">${esc(d)}</div></div>`).join('')}</div><div class="grid-two"><section class="card"><div class="card-head"><h2>${T('Next actions','المتابعات القادمة')}</h2><button class="small" data-nav="actions">${T('View all','عرض الكل')}</button></div>${rows('actions').filter(r=>r.status!=='Done').sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,6).map(r=>`<div class="list-item"><div><button class="link-button" data-edit="${r.id}">${esc(r.name)}</button><p>${esc(r.owner||T('Unassigned','غير مسند'))} · ${esc(name(r.opportunity_id))}</p></div><span class="badge ${overdue(r)?'overdue':''}">${esc(r.due||T('No date','دون تاريخ'))}</span></div>`).join('')||empty(T('Turn discussions into actions','حوّل النقاش إلى إجراءات'),T('Add the next step, its owner and due date.','أضف الخطوة القادمة والمسؤول وموعد التنفيذ.'),'actions')}</section><section class="card"><div class="card-head"><h2>${T('Supplier coverage','تغطية الموردين')}</h2><button class="small" data-nav="suppliers">${T('Explore','استعراض')}</button></div>${sectors.map(s=>{const n=suppliers.filter(r=>r.sector===s).length;return `<div class="bar-row"><span>${esc(s)}</span><progress value="${n}" max="${Math.max(suppliers.length,1)}" aria-label="${esc(s)}"></progress><strong>${n}</strong></div>`}).join('')}<div class="note">${T('Reference snapshot: 9 August 2026. Imported findings have not been independently rechecked.','بيانات المرجع بتاريخ 9 أغسطس 2026. لم تتم إعادة التحقق مستقلاً من النتائج المستوردة.')}</div></section><section class="card"><div class="card-head"><h2>${T('Opportunity stages','مراحل الفرص')}</h2><button class="small" data-nav="opportunities">${T('Open pipeline','عرض الفرص')}</button></div>${stages.map(s=>`<div class="bar-row"><span>${esc(s)}</span><progress value="${opps.filter(r=>r.stage===s).length}" max="${Math.max(opps.length,1)}" aria-label="${esc(s)}"></progress><strong>${opps.filter(r=>r.stage===s).length}</strong></div>`).join('')}</section><section class="card"><div class="card-head"><h2>${T('Recent activity','آخر التحديثات')}</h2></div>${state.audit.slice(0,6).map(a=>`<div class="list-item"><div><strong>${esc(name(a.record_id)||a.kind)}</strong><p>${esc(a.action)}</p></div><time class="activity-time">${esc(a.at.slice(0,10))}</time></div>`).join('')||`<p class="muted">${T('Your changes will appear here.','ستظهر تغييراتك هنا.')}</p>`}<button data-nav="sources">${T('Manage research sources','إدارة مصادر البحث')}</button></section></div>`}
function filtered(kind=route){return rows(kind).filter(r=>(!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase()))&&Object.entries(filters).every(([k,v])=>!v||(k==='shortlisted'?!!r.shortlisted:String(r[k]||'')===v))).sort((a,b)=>String(a.name).localeCompare(String(b.name))*sortDir)}
function filterSelect(key,values,label){return `<select data-filter="${key}" aria-label="${label}">${options(values,filters[key],label)}</select>`}
function tablePage(){const info=nav.find(n=>n[0]===route),all=filtered(),visible=all.slice((page-1)*25,page*25);let cols=[],cells;
 if(route==='suppliers'){cols=[T('Company','الشركة'),T('Products / group','المنتجات والمجموعة'),T('Saudi presence','الحضور بالسعودية'),T('Evidence','الدليل'),T('Source','المصدر')];cells=r=>[`<button class="link-button company" data-edit="${r.id}">${r.shortlisted?'★ ':''}${esc(r.name)}</button><p>${esc(r.country)} · ${esc(r.sector)}</p>`,`<div>${esc(r.group)}</div><p>${esc(r.products)}</p>`,`${badge(r.presence)}<p>${esc(r.finding)}</p>`,`${esc(r.evidence||'—')}<p>${T('Snapshot','لقطة المرجع')}: ${esc(r.snapshot_date||'—')}<br>${T('Rechecked','آخر تحقق')}: ${esc(r.verified_date||'—')}</p>`,`${r.source_url?`<a href="${url(r.source_url)}" target="_blank" rel="noopener noreferrer">${T('Evidence link','رابط الدليل')}</a>`:'—'}<p>${r.website?`<a href="${url(r.website)}" target="_blank" rel="noopener noreferrer">${T('Company website','موقع الشركة')}</a>`:''}</p>`]}
 if(route==='opportunities'){cols=[T('Opportunity','الفرصة'),T('Account / partner','العميل والشريك'),T('Stage','المرحلة'),T('Value','القيمة'),T('Next action','الخطوة القادمة')];cells=r=>[`<button class="link-button company" data-edit="${r.id}">${esc(r.name)}</button><p>${esc(r.owner||'—')} · ${esc(r.sector||'—')}</p>`,`${esc(name(r.account_id)||'—')}<p>${esc(name(r.supplier_id))}</p>`,badge(r.stage),r.value!==''&&r.value!=null?`${esc(r.currency)} ${num(r.value)}<p>${T('Probability','الاحتمال')}: ${r.probability??'—'}%</p>`:'—',`${esc(r.next_action||'—')}<p>${esc(r.due||'')}</p>`]}
 if(route==='accounts'){cols=[T('Account','الجهة'),T('Type / sector','النوع والقطاع'),T('Contact','جهة الاتصال'),T('Email / phone','البريد والهاتف'),T('Owner','المسؤول')];cells=r=>[`<button class="link-button company" data-edit="${r.id}">${esc(r.name)}</button><p>${esc(r.location)}</p>`,`${esc(r.account_type)}<p>${esc(r.sector)}</p>`,`${esc(r.contact)}<p>${esc(r.contact_role)}</p>`,`${esc(r.email)}<p>${esc(r.phone)}</p>`,esc(r.owner)]}
 if(route==='actions'){cols=[T('Action','الإجراء'),T('Linked opportunity','الفرصة المرتبطة'),T('Owner','المسؤول'),T('Due','الموعد'),T('Status','الحالة')];cells=r=>[`<button class="link-button company" data-edit="${r.id}">${esc(r.name)}</button><p>${esc(r.priority)}</p>`,esc(name(r.opportunity_id)||'—'),esc(r.owner||'—'),`<span class="${overdue(r)?'badge overdue':''}">${esc(r.due||'—')}</span>`,`${badge(r.status)} ${r.status!=='Done'?`<button class="small" data-complete="${r.id}">${T('Complete','إكمال')}</button>`:''}`]}
 if(route==='meetings'){cols=[T('Meeting','الاجتماع'),T('Date','التاريخ'),T('Account','الجهة'),T('Attendees','الحضور'),T('Decision / follow-up','القرارات والمتابعة')];cells=r=>[`<button class="link-button company" data-edit="${r.id}">${esc(r.name)}</button>`,esc(r.date||'—'),esc(name(r.account_id)||'—'),esc(r.attendees||'—'),`<p>${esc((r.decisions||r.notes||'').slice(0,180))}</p>`]}
 const controls=route==='suppliers'?filterSelect('country',['China','France'],T('All origins','كل الدول'))+filterSelect('presence',[['no',T('No presence found','لم يُعثر على حضور')],['maybe',T('Unconfirmed','غير مؤكد')],['yes',T('Presence found','حضور موجود')]],T('All findings','كل النتائج'))+filterSelect('sector',sectors,T('All sectors','كل القطاعات'))+filterSelect('group',[...new Set(rows('suppliers').map(r=>r.group).filter(Boolean))].sort(),T('All product groups','كل المجموعات'))+filterSelect('shortlisted',[['yes',T('Shortlisted only','القائمة المختصرة')]],T('All companies','كل الشركات')):route==='opportunities'?filterSelect('stage',stages,T('All stages','كل المراحل'))+filterSelect('owner',[...new Set(rows(route).map(r=>r.owner).filter(Boolean))],T('All owners','كل المسؤولين')):route==='actions'?filterSelect('status',['Open','In progress','Done'],T('All statuses','كل الحالات')):'';
 return head(T(info[2],info[3]),`${num(all.length)} ${T('records · changes are saved locally','سجل · تحفظ التغييرات محلياً')}`,`<button class="primary" data-new="${route}">+ ${T('Add record','إضافة سجل')}</button>`)+(route==='suppliers'?`<div class="note">${T('“No presence found” describes the research result, not proof of an available agency. Review the cited source and confirm the territory with the company.','«لم يُعثر على حضور» تصف نتيجة البحث، ولا تثبت توفر الوكالة. راجع المصدر وأكد نطاق التمثيل مع الشركة.')}</div>`:'')+`<div class="toolbar"><input type="search" id="search" value="${esc(query)}" placeholder="${T('Search names, products, notes…','ابحث بالأسماء والمنتجات والملاحظات…')}" aria-label="${T('Search records','البحث في السجلات')}">${controls}<button id="clear">${T('Clear','مسح')}</button><button id="export-table">Excel</button><button id="import-table">${T('Import CSV','استيراد CSV')}</button></div>${all.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${cols.map((c,i)=>`<th>${i===0?`<button class="link-button" id="sort">${c} ${sortDir===1?'↑':'↓'}</button>`:c}</th>`).join('')}</tr></thead><tbody>${visible.map(r=>`<tr>${cells(r).map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="pager"><span>${(page-1)*25+1}–${Math.min(page*25,all.length)} / ${all.length}</span><div><button id="prev" ${page===1?'disabled':''}>${T('Previous','السابق')}</button> <button id="next" ${page*25>=all.length?'disabled':''}>${T('Next','التالي')}</button></div></div>`:empty(T('No records to show','لا توجد سجلات'),T('Add a record, import a CSV, or change your filters.','أضف سجلاً أو استورد CSV أو غيّر المرشحات.'),route)}`}
function sourcePage(){return head(T('Sources & inputs','المصادر والمدخلات'),T('Choose what the assistant can use for each task.','حدد ما يستطيع المساعد استخدامه لكل مهمة.'),`<button class="primary" data-new="sources">+ ${T('Add source','إضافة مصدر')}</button>`)+`<div class="note">${T('Add website links, paste text, or extract text from TXT, Markdown and Word files. Group sources by task. Files and notes stay local until you explicitly include them in an AI request.','أضف روابط مواقع أو نصوصاً، أو استخرج النص من ملفات TXT وMarkdown وWord. صنّف المصادر حسب المهمة. تبقى الملفات والملاحظات محلية حتى تختار إرسالها ضمن طلب الذكاء الاصطناعي.')}</div><div class="toolbar"><input id="search" type="search" value="${esc(query)}" placeholder="${T('Search your sources…','ابحث في مصادرك…')}" aria-label="${T('Search sources','بحث المصادر')}">${filterSelect('task',taskNames.map(([id,en,ar])=>[id,T(en,ar)]),T('All tasks','كل المهام'))}<button data-new="profiles">${T('New task profile','إعداد مهمة جديد')}</button></div>${rows('profiles').length?`<div class="card"><h2>${T('Saved task profiles','إعدادات المهام المحفوظة')}</h2><div class="pillrow">${rows('profiles').map(r=>`<button data-edit="${r.id}">${esc(r.name)}</button>`).join('')}</div></div>`:''}<div class="source-grid">${filtered('sources').map(r=>`<article class="source-card"><div class="card-head"><h3>${esc(r.name)}</h3>${badge(r.enabled===false?T('Disabled','معطل'):T('Enabled','مفعّل'))}</div><p>${esc(r.task||T('General','عام'))} · ${esc(r.source_type||'Text')} · ${esc(r.date||'—')}</p>${r.url?`<a href="${url(r.url)}" target="_blank" rel="noopener noreferrer">${esc(new URL(r.url).hostname)}</a>`:''}<p>${esc((r.content||r.notes||T('No text added. A website link can be used for domain-scoped web research.','لم يُضف نص. يمكن استخدام الرابط لتحديد نطاق البحث بالموقع.')).slice(0,190))}</p><p>${num((r.content||'').length)} ${T('characters available','حرف متاح')}</p><div class="pillrow"><button data-edit="${r.id}">${T('Edit source','تعديل المصدر')}</button><button data-source-research="${r.id}">${T('Use in research','استخدم في البحث')}</button></div></article>`).join('')}</div>${!filtered('sources').length?empty(T('Build your research library','جهّز مصادر بحثك'),T('Create a source, assign its task, then choose it when you research.','أضف مصدراً وحدد نوع مهمته ثم اختره عند البحث.'),'sources'):''}`}
let researchDraft={query:'',context:'',profile:'supplier',mode:'web',source_ids:[],task_instructions:templates.supplier,consent:false};
function researchPage(){const sources=rows('sources').filter(r=>r.enabled!==false);return head(T('Research workspace','مساحة البحث'),T('Ask a question. Choose its inputs. Keep the evidence.','اكتب المهمة، حدد مدخلاتها، واحتفظ بأدلتها.'))+`<div class="research-grid"><section class="card"><form id="research-form" class="form-stack"><label>${T('Task profile','إعداد المهمة')}<select id="research-profile">${options([...taskNames.map(([id,en,ar])=>[id,T(en,ar)]),...rows('profiles').map(r=>[r.id,r.name])],researchDraft.profile)}</select></label><label>${T('Your question or task','سؤالك أو مهمتك')}<textarea name="query" rows="4" required placeholder="${T('Find suppliers of robotic tank inspection and check their Saudi representation…','ابحث عن موردي الفحص الروبوتي للخزانات وتحقق من تمثيلهم في السعودية…')}">${esc(researchDraft.query)}</textarea></label><label>${T('Research scope','نطاق البحث')}<select name="mode">${options([['web',T('Web + selected inputs','الإنترنت والمدخلات المختارة')],['domains',T('Selected website domains + inputs','نطاقات المواقع المختارة والمدخلات')],['local',T('Selected text and notes only','النصوص والملاحظات المختارة فقط')]],researchDraft.mode)}</select></label><div><div class="card-head"><h3>${T('Sources for this request','مصادر هذا الطلب')}</h3><button type="button" class="small" data-new="sources">+ ${T('Add','إضافة')}</button></div><div class="source-picker">${sources.map(r=>`<label class="check"><input type="checkbox" name="source" value="${r.id}" ${researchDraft.source_ids.includes(r.id)?'checked':''}><span>${esc(r.name)}<small>${esc(r.source_type||'Text')} · ${num(Math.min((r.content||'').length,50000))} ${T('text characters will be sent','حرف نصي سيُرسل')}${(r.content||'').length>50000?' · '+T('truncated to first 50,000','أول 50,000 حرف فقط'):''}</small></span></label>`).join('')||`<span class="muted">${T('No sources yet. Add your websites and documents.','لا توجد مصادر بعد. أضف مواقعك ومستنداتك.')}</span>`}</div></div><label>${T('Task instructions (editable)','تعليمات المهمة (قابلة للتعديل)')}<textarea name="task_instructions" rows="3">${esc(researchDraft.task_instructions)}</textarea></label><label>${T('Additional notes to include','ملاحظات إضافية للإرسال')}<textarea name="context" rows="3">${esc(researchDraft.context)}</textarea></label><label class="check"><input name="consent" type="checkbox" required ${researchDraft.consent?'checked':''}><span>${T('Send this question, instructions and selected source text to OpenAI. API usage may incur charges.','إرسال السؤال والتعليمات ونصوص المصادر المحددة إلى OpenAI. قد تترتب رسوم استخدام API.')}</span></label><div class="note">${T('Website scope limits domains, including their subdomains; it does not guarantee every linked page is read. For exact document-only answers, supply the text and choose “Selected text and notes only”.','تحديد المواقع يقيد نطاقات البحث ونطاقاتها الفرعية، ولا يضمن قراءة كل صفحة. للإجابة من مستند بعينه فقط، أضف نصه واختر «النصوص والملاحظات المختارة فقط».')}</div><button class="primary" type="submit" ${busy?'disabled':''}>${busy?T('Researching…','البحث جارٍ…'):T('Run research','تنفيذ البحث')}</button>${!state.ai_connected?`<p class="muted">${T('AI is not connected. Add your API key in Settings. You can also copy the prompt and use it in ChatGPT.','الذكاء الاصطناعي غير متصل. أضف مفتاح API في الإعدادات، أو انسخ البرومبت واستخدمه في ChatGPT.')}</p>`:''}<div class="pillrow"><button type="button" id="copy-prompt">${T('Copy full prompt','نسخ البرومبت الكامل')}</button><button type="button" id="browser-search">${T('Search in browser','بحث بالمتصفح')}</button></div></form></section><div><section class="card"><div class="card-head"><h2>${T('Research result','نتيجة البحث')}</h2>${researchResult?`<button id="research-to-report" class="small">${T('Use in report','استخدم في تقرير')}</button>`:''}</div>${busy?`<p class="busy">${T('Checking sources and preparing a response. This can take a few minutes.','جارٍ البحث بالمصادر وإعداد الإجابة. قد يستغرق ذلك بضع دقائق.')}</p>`:researchResult?resultHTML(researchResult):empty(T('Evidence before decisions','الأدلة قبل القرار'),T('Your answer, citations and exact source selection will be saved here.','تحفظ هنا الإجابة والاستشهادات والمصادر التي اخترتها.'))}</section><section class="card"><h2>${T('Saved research','الأبحاث المحفوظة')}</h2>${rows('research').slice(0,15).map(r=>`<div class="list-item"><button class="link-button" data-result="${r.id}">${esc(r.name)}</button><time class="activity-time">${r.created.slice(0,10)}</time></div>`).join('')||`<p class="muted">${T('No saved research yet.','لا توجد أبحاث محفوظة بعد.')}</p>`}</section></div></div>`}
function resultHTML(r){let content='';for(const b of r.blocks||[{text:r.answer||'',annotations:[]}]){const chars=Array.from(b.text||'');let pos=0;const anns=[...(b.annotations||[])].sort((a,b)=>a.start_index-b.start_index);for(const a of anns){if(a.start_index<pos||!url(a.url))continue;content+=esc(chars.slice(pos,a.start_index).join(''))+`<a href="${url(a.url)}" target="_blank" rel="noopener noreferrer" title="${esc(a.title)}">${esc(chars.slice(a.start_index,a.end_index).join('')||a.title||'Source')}</a>`;pos=a.end_index}content+=esc(chars.slice(pos).join(''))+'\n\n'}const citations=(r.blocks||[]).flatMap(b=>b.annotations||[]);return `${r.status&&r.status!=='completed'?`<div class="note warn">${T('The API marked this result incomplete. Treat it as a partial answer.','صنّفت الخدمة الإجابة بأنها غير مكتملة. تعامل معها كإجابة جزئية.')}</div>`:''}<p class="muted">${esc(r.created?.slice(0,10)||'')} · ${esc(r.model||'')} · ${esc(r.mode||'')}</p><div class="research-answer" dir="auto">${content}</div><div class="citation-list"><strong>${T('Sources and input record','المصادر وسجل المدخلات')}</strong>${[...new Map(citations.map(a=>[a.url,a])).values()].map(a=>`<div><a href="${url(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.title||a.url)}</a></div>`).join('')}${(r.source_manifest||[]).map(a=>`<div>[${esc(a.label)}] ${esc(a.name)} · ${esc(a.updated?.slice(0,10)||'')} · ${a.characters_sent} ${T('characters sent','حرف أُرسل')}${a.url?` · <a href="${url(a.url)}" target="_blank" rel="noopener noreferrer">${T('Link','الرابط')}</a>`:''}</div>`).join('')}</div>`}
function reportsPage(){return head(T('Report builder','إعداد التقارير'),T('Generate from saved records, edit the wording, then export.','أنشئ التقرير من السجلات، حرر النص، ثم صدّره.'))+`<div class="card screen-only"><div class="toolbar"><select id="report-type" aria-label="${T('Report type','نوع التقرير')}">${options([['weekly',T('BD management update','تحديث تطوير الأعمال')],['suppliers',T('Supplier screening summary','ملخص فحص الموردين')],['meeting',T('Meeting minutes','محضر اجتماع')]],'weekly')}</select><select id="report-owner" aria-label="${T('Owner','المسؤول')}">${options([...new Set(state.records.map(r=>r.owner).filter(Boolean))],undefined,T('All owners','كل المسؤولين'))}</select><label>${T('Updated from','تحديثات من')}<input id="report-from" type="date"></label><label>${T('Through','إلى')}<input id="report-to" type="date" value="${day()}"></label><button id="generate-report" class="primary">${T('Generate','إنشاء')}</button></div><p class="muted">${T('Date filters use each record’s last saved update. Currency totals are kept separate; no exchange rate is assumed.','يعتمد التاريخ على آخر تحديث محفوظ لكل سجل. تعرض إجماليات العملات منفصلة دون افتراض سعر صرف.')}</p></div><section class="card"><label class="screen-only">${T('Report title','عنوان التقرير')}<input id="report-title" value="${esc(reportTitle)}"></label><br><textarea class="report-editor" id="report-text" dir="auto" placeholder="${T('Choose a report above, or send a research result here.','اختر نوع التقرير أو أرسل نتيجة بحث إلى هنا.')}">${esc(reportText)}</textarea><h1 class="print-only report-title">${esc(reportTitle)}</h1><div id="print-report" class="print-only report-sheet" dir="auto">${esc(reportText)}</div><div class="pillrow screen-only"><button id="word-report" class="primary">${T('Download Word','تنزيل Word')}</button><button id="print-report-button">${T('Print / Save PDF','طباعة / حفظ PDF')}</button><button id="text-report">${T('Download text','تنزيل النص')}</button></div></section>`}
function settingsPage(){return head(T('Settings & backup','الإعدادات والنسخ الاحتياطية'),T('Keep control of your data and optional AI connection.','تحكم في بياناتك واتصال الذكاء الاصطناعي الاختياري.'))+`<div class="settings-grid"><section class="card"><h2>${T('Optional AI research','بحث الذكاء الاصطناعي الاختياري')}</h2><p class="${state.ai_connected?'good':'muted'}">${state.ai_connected?T('Key provided · not yet validated by a live request','أُدخل المفتاح · يتحقق الاتصال عند تنفيذ طلب'):T('Not connected','غير متصل')}</p><form id="settings-form" class="form-stack"><label>OpenAI API key<input name="api_key" type="password" autocomplete="off" placeholder="${T('Leave blank to keep current key','اتركه فارغاً للاحتفاظ بالمفتاح الحالي')}"></label><label>${T('API model','نموذج API')}<input name="model" value="${esc(state.model||'gpt-5-mini')}"></label><p class="muted">${T('The key is held in memory for this session and is excluded from backups. Enter it again after restarting, or set OPENAI_API_KEY in your Windows environment.','يحتفظ بالمفتاح في ذاكرة هذه الجلسة ويُستبعد من النسخ الاحتياطية. أدخله بعد إعادة التشغيل أو اضبط متغير OPENAI_API_KEY في Windows.')}</p><button class="primary">${T('Apply connection settings','تطبيق إعدادات الاتصال')}</button><button type="button" id="disconnect">${T('Disconnect AI','فصل الذكاء الاصطناعي')}</button></form><p><a href="https://developers.openai.com/api/docs/guides/tools-web-search" target="_blank" rel="noopener noreferrer">${T('OpenAI web research documentation','توثيق البحث في OpenAI')}</a></p></section><section class="card"><h2>${T('Backup and recovery','النسخ الاحتياطي والاسترجاع')}</h2><p>${T('Download a backup of all records and attachments. Restore merges missing records and never overwrites records already on this computer.','نزّل نسخة من جميع السجلات والمرفقات. يضيف الاسترجاع السجلات المفقودة ولا يستبدل السجلات الموجودة على هذا الجهاز.')}</p><div class="pillrow"><button class="primary" id="backup">${T('Download backup','تنزيل نسخة احتياطية')}</button><button id="restore">${T('Merge a backup','دمج نسخة احتياطية')}</button></div><h3>${T('Local data folder','مجلد البيانات المحلي')}</h3><p class="text-wrap" dir="ltr">${esc(state.data_folder)}</p><p class="muted">${T('This personal edition listens only on your own computer. It uses your Windows account’s access controls and has no separate multi-user login.','تعمل النسخة الشخصية على جهازك فقط، وتعتمد على صلاحيات حساب Windows. لا تتضمن تسجيل دخول لعدة مستخدمين.')}</p><h3>${T('Reference data','بيانات المرجع')}</h3><a href="https://chinesseandfrenshrev02.netlify.app/" target="_blank" rel="noopener noreferrer">Chinese & French Supplier Screening</a><p class="muted">${T('271 imported supplier records. Original snapshot: 9 August 2026. Import date: 26 September 2026. Supplier facts were not independently reverified.','271 سجل مورد مستورد. تاريخ بيانات المرجع: 9 أغسطس 2026. تاريخ الاستيراد: 26 سبتمبر 2026. لم يُعد التحقق مستقلاً من معلومات الموردين.')}</p></section></div>`}

function fields(kind){const f=(id,en,ar,type='text',values)=>({id,label:T(en,ar),type,values});const ref=(kind)=>rows(kind).map(r=>[r.id,r.name]);const common=[f('owner','Owner','المسؤول'),f('notes','Notes','الملاحظات','textarea')];
 const definitions={
 suppliers:[f('name','Company name','اسم الشركة'),f('country','Country','الدولة'),f('sector','Business line','القطاع','select',sectors),f('group','Product group','مجموعة المنتجات'),f('products','Products / capabilities','المنتجات والقدرات','textarea'),f('presence','Saudi presence finding','نتيجة الحضور بالسعودية','select',[['maybe',T('Unconfirmed','غير مؤكد')],['no',T('No presence found','لم يُعثر على حضور')],['yes',T('Presence found','حضور موجود')]]),f('finding','What was found','ما تم العثور عليه','textarea'),f('evidence','Evidence level','مستوى الدليل','select',['Unverified','Partial','Documented']),f('website','Company website','موقع الشركة','url'),f('source_url','Evidence URL','رابط الدليل','url'),f('source_note','Source notes','ملاحظات المصدر','textarea'),f('snapshot_date','Source snapshot date','تاريخ بيانات المصدر','date'),f('verified_date','Date YOU rechecked the finding','تاريخ إعادة تحققك من النتيجة','date'),f('shortlisted','Add to shortlist','إضافة للقائمة المختصرة','checkbox'),...common],
 accounts:[f('name','Account name','اسم الجهة'),f('account_type','Account type','نوع الجهة','select',['Operator','EPC','Drilling contractor','Industrial client','Partner','Other']),f('sector','Sector','القطاع','select',sectors),f('location','Location','الموقع'),f('contact','Primary contact','جهة الاتصال الرئيسية'),f('contact_role','Contact role','المنصب'),f('email','Email','البريد','email'),f('phone','Phone','الهاتف'),f('website','Website','الموقع الإلكتروني','url'),...common],
 opportunities:[f('name','Opportunity title','عنوان الفرصة'),f('account_id','Customer / account','العميل','select',ref('accounts')),f('supplier_id','Supplier / partner','المورد أو الشريك','select',ref('suppliers')),f('sector','Sector','القطاع','select',sectors),f('stage','Stage','المرحلة','select',stages),f('value','Estimated value (blank if unknown)','القيمة التقديرية (فارغة إذا لم تُعرف)','number'),f('currency','Currency','العملة','select',['SAR','USD','EUR','GBP','AED']),f('probability','Probability % (blank if unknown)','الاحتمال % (فارغ إذا لم يُعرف)','number'),f('close_date','Expected close date','تاريخ الإغلاق المتوقع','date'),f('need','Customer need / use case','حاجة العميل والاستخدام','textarea'),f('approvals','Technical acceptance / localisation','القبول الفني والتوطين','textarea'),f('risks','Risks / competition','المخاطر والمنافسة','textarea'),f('next_action','Next action','الخطوة القادمة'),f('due','Next action due','موعد الخطوة القادمة','date'),...common],
 actions:[f('name','Action','الإجراء'),f('opportunity_id','Linked opportunity','الفرصة المرتبطة','select',ref('opportunities')),f('status','Status','الحالة','select',['Open','In progress','Done']),f('priority','Priority','الأولوية','select',['Normal','High','Low']),f('due','Due date','الموعد','date'),...common],
 meetings:[f('name','Meeting title','عنوان الاجتماع'),f('date','Date','التاريخ','date'),f('account_id','Account','الجهة','select',ref('accounts')),f('attendees','Attendees','الحضور','textarea'),f('agenda','Agenda','جدول الأعمال','textarea'),f('decisions','Decisions / agreements','القرارات والاتفاقات','textarea'),f('follow_up','Actions and owners','الإجراءات والمسؤولون','textarea'),...common],
 sources:[f('name','Source name','اسم المصدر'),f('source_type','Source type','نوع المصدر','select',['Website','Document','Notes','Email excerpt','Research brief']),f('task','Use for task','نوع المهمة','select',taskNames.map(([id,en,ar])=>[id,T(en,ar)])),f('url','Source URL (optional)','رابط المصدر (اختياري)','url'),f('date','Document / publication date','تاريخ المستند أو النشر','date'),f('priority','Priority','الأولوية','select',['Primary','Supporting','Background']),f('content','Source text used by the assistant','نص المصدر الذي يستخدمه المساعد','longtext'),f('enabled','Available for research','متاح للاستخدام في البحث','checkbox'),...common],
 profiles:[f('name','Task profile name','اسم إعداد المهمة'),f('mode','Default research scope','نطاق البحث الافتراضي','select',[['web',T('Web + inputs','الإنترنت والمدخلات')],['domains',T('Selected website domains','نطاقات المواقع المحددة')],['local',T('Selected text only','النصوص المحددة فقط')]]),f('source_ids','Default sources','المصادر الافتراضية','multi',ref('sources')),f('task_instructions','Task instructions','تعليمات المهمة','longtext')]
 };return definitions[kind]||[]}
let editRecord=null,pendingFile=null;
function fieldHTML(f,r){const v=r[f.id]??'';if(f.type==='checkbox')return `<label class="check span-two"><input type="checkbox" name="${f.id}" ${v?'checked':''}>${f.label}</label>`;if(f.type==='multi')return `<div class="span-two"><h3>${f.label}</h3><div class="source-picker">${(f.values||[]).map(([id,n])=>`<label class="check"><input type="checkbox" name="${f.id}" value="${id}" ${(Array.isArray(v)?v:[]).includes(id)?'checked':''}>${esc(n)}</label>`).join('')||T('Add sources first.','أضف المصادر أولاً.')}</div></div>`;let input;if(f.type==='select')input=`<select name="${f.id}">${options(f.values||[],v,T('Select…','اختر…'))}</select>`;else if(['textarea','longtext'].includes(f.type))input=`<textarea name="${f.id}" rows="${f.type==='longtext'?8:3}" dir="auto">${esc(v)}</textarea>`;else input=`<input name="${f.id}" type="${f.type}" value="${esc(v)}" ${f.id==='name'?'required maxlength="300"':''} ${f.type==='number'?'min="0" step="any"':''} ${f.id==='probability'?'max="100"':''}>`;return `<label class="${['textarea','longtext'].includes(f.type)?'span-two':''}">${f.label}${input}</label>`}
function openEditor(kind,id){captureResearch();editRecord=id?get(id):{kind,presence:'maybe',enabled:true,stage:'Identified',currency:'SAR',status:'Open',priority:kind==='sources'?'Primary':'Normal',mode:'web'};pendingFile=null;const r=editRecord,m=$('#modal');m.className='modal';m.innerHTML=`<form id="record-form"><div class="modal-head"><h2 id="modal-title">${r.id?T('Edit record','تعديل السجل'):T('Add record','إضافة سجل')}</h2><button type="button" data-close aria-label="${T('Close','إغلاق')}">×</button></div><div class="modal-body"><div class="form-grid">${fields(kind).map(f=>fieldHTML(f,r)).join('')}</div>${kind==='sources'?`<div class="note">${T('Extract text from PDF, PPTX, XLSX, DOCX, TXT, MD and CSV. Scans and images need OCR.','استخرج النص من PDF وPPTX وXLSX وDOCX وTXT وCSV. الصور والمسح الضوئي تحتاج OCR.')}</div><button type="button" id="extract-source">${T('Import source text from file','استيراد نص المصدر من ملف')}</button><span id="pending-file" class="muted"></span>`:''}${r.id?`<hr><h3>${T('Attachments','المرفقات')}</h3><div id="attachment-list"></div><button type="button" id="attach-file">${T('Attach a file (up to 10 MB)','إرفاق ملف (حتى 10 MB)')}</button>`:''}${r.provenance?`<p class="muted">${esc(r.provenance)}</p>`:''}</div><div class="modal-footer">${r.id?`<button class="danger" type="button" id="delete-record">${T('Delete','حذف')}</button>`:''}<button type="button" data-close>${T('Cancel','إلغاء')}</button><button type="submit" class="primary">${T('Save changes','حفظ التغييرات')}</button></div></form>`;m.showModal();m.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>m.close());$('#record-form').onsubmit=saveRecord;if(r.id){loadAttachments(r.id);$('#attach-file').onclick=()=>pickFile('',async file=>{await uploadFile(r.id,file);await loadAttachments(r.id);toast(T('File attached','تم إرفاق الملف'))});$('#delete-record').onclick=async()=>{if(!confirm(T('Delete this record? Linked records will be kept.','حذف هذا السجل؟ ستبقى السجلات المرتبطة.')))return;await act(async()=>{await api('delete',{id:r.id,version:r.version});m.close();await refresh();render()})}}if(kind==='sources')$('#extract-source').onclick=()=>pickFile('.txt,.md,.csv,.docx,.pptx,.xlsx,.pdf',async file=>{const extracted=await api('extract',{name:file.name,data:await b64(file)});$('#record-form [name=content]').value=extracted.text;const n=$('#record-form [name=name]');if(!n.value)n.value=file.name;pendingFile=file;$('#pending-file').textContent=' '+file.name;toast(T('Text extracted. Review it before saving.','تم استخراج النص. راجعه قبل الحفظ.'))});}
async function saveRecord(e){e.preventDefault();const form=e.target,fd=new FormData(form),kind=editRecord.kind,record={...editRecord};for(const f of fields(kind)){if(f.type==='checkbox')record[f.id]=fd.has(f.id);else if(f.type==='multi')record[f.id]=fd.getAll(f.id);else record[f.id]=String(fd.get(f.id)||'').trim()}const button=form.querySelector('button[type=submit]');button.disabled=true;try{const r=await api('save',{kind,record,id:editRecord.id,version:editRecord.version});if(pendingFile){try{await uploadFile(r.id,pendingFile)}catch(err){toast(T('Record saved, but attachment failed: ','حفظ السجل، لكن تعذر إرفاق الملف: ')+err.message,true)}}$('#modal').close();await refresh();render();toast(T('Saved on your computer','حُفظ على جهازك'))}catch(err){toast(err.message,true);button.disabled=false}}
async function loadAttachments(id){try{const a=await api('attachments?id='+encodeURIComponent(id));const e=$('#attachment-list');if(!e)return;e.innerHTML=a.map(f=>`<div class="file-row"><button type="button" class="link-button" data-file="${f.id}" data-filename="${esc(f.name)}">${esc(f.name)}</button><small>${num(f.size/1024)} KB</small></div>`).join('')||`<p class="muted">${T('No attachments','لا توجد مرفقات')}</p>`;e.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>act(async()=>download(await api('file/'+b.dataset.file,undefined,true),b.dataset.filename)))}catch(e){toast(e.message,true)}}
async function b64(file){if(file.size>10*1024*1024)throw Error(T('Maximum file size is 10 MB.','الحد الأعلى للملف 10 MB.'));return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('File read failed'));reader.readAsDataURL(file)})}
async function uploadFile(id,file){await api('upload',{record_id:id,name:file.name,data:await b64(file)})}
function pickFile(accept,fn){const e=document.createElement('input');e.type='file';e.accept=accept;e.onchange=()=>{if(e.files[0])act(()=>fn(e.files[0]))};e.click()}
async function act(fn){try{await fn()}catch(e){toast(e.message,true)}}
function captureResearch(){const f=$('#research-form');if(!f)return;const d=new FormData(f);researchDraft={...researchDraft,query:String(d.get('query')||''),context:String(d.get('context')||''),mode:d.get('mode'),source_ids:d.getAll('source'),task_instructions:String(d.get('task_instructions')||''),consent:d.has('consent'),profile:$('#research-profile').value}}
async function copy(text){try{await navigator.clipboard.writeText(text)}catch{const e=document.createElement('textarea');e.value=text;document.body.append(e);e.select();document.execCommand('copy');e.remove()}toast(T('Copied','تم النسخ'))}
function fullPrompt(){captureResearch();const s=rows('sources').filter(r=>r.enabled!==false&&researchDraft.source_ids.includes(r.id));return `TASK: ${researchDraft.query}\n\nINSTRUCTIONS: ${researchDraft.task_instructions}\n\nSCOPE: ${researchDraft.mode==='local'?'Use only the supplied text; say when evidence is missing.':researchDraft.mode==='domains'?'Search only these domains and their subdomains: '+s.map(r=>{try{return new URL(r.url).hostname}catch{return ''}}).filter(Boolean).join(', '):'Search reliable public sources, prioritising the selected sources.'}\nCite factual claims. Distinguish verified facts, inferences and unknowns. Do not equate no result found with no Saudi agent existing.\n\nNOTES: ${researchDraft.context}\n\nSOURCES:\n${s.map((r,i)=>`[S${i+1}] ${r.name}\nURL: ${r.url||''}\n${(r.content||'').slice(0,50000)}`).join('\n\n')}`}
function columnsFor(kind){return fields(kind).filter(f=>f.type!=='multi').map(f=>f.id)}
function parseCSV(text){const out=[];let row=[],cell='',quote=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))out.push(row);row=[];cell=''}else cell+=c}if(quote)throw Error('CSV contains an unclosed quote.');row.push(cell);if(row.some(x=>x.trim()))out.push(row);if(out.length<1)return[];const keys=out.shift().map(k=>k.trim());if(!keys.includes('name'))throw Error(T('CSV must contain a name column. Use the exported template headers.','يجب أن يحتوي CSV على عمود name. استخدم عناوين القالب المصدر.'));return out.map(r=>Object.fromEntries(keys.map((k,i)=>[k,r[i]||''])))}
function importTable(){const kind=route,m=$('#modal');m.className='modal';m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${T('Import CSV','استيراد CSV')}</h2><button data-close>×</button></div><div class="modal-body"><p>${T('The CSV must use the template column names. Existing names are skipped; imports never overwrite verified records. Review imported facts before using them.','يجب استخدام عناوين أعمدة القالب. تُتخطى الأسماء الموجودة ولا تُستبدل السجلات. راجع المعلومات المستوردة قبل استخدامها.')}</p><div class="pillrow"><button id="template">${T('Download CSV template','تنزيل قالب CSV')}</button><button class="primary" id="choose-csv">${T('Select CSV file','اختر ملف CSV')}</button></div><div id="import-preview"></div></div>`;m.showModal();m.querySelector('[data-close]').onclick=()=>m.close();$('#template').onclick=()=>download(new Blob(['\ufeff'+columnsFor(kind).join(',')+'\r\n'],{type:'text/csv;charset=utf-8'}),'BD-Import-Template.csv');$('#choose-csv').onclick=()=>pickFile('.csv',async file=>{const data=parseCSV(await file.text());for(const r of data){for(const k of ['shortlisted','enabled'])if(k in r)r[k]=['true','1','yes'].includes(r[k].toLowerCase())}$('#import-preview').innerHTML=`<p>${num(data.length)} ${T('rows found','صف موجود')}.</p><ul>${data.slice(0,6).map(r=>`<li>${esc(r.name)}</li>`).join('')}</ul><button id="confirm-import" class="primary">${T('Import these records','استيراد هذه السجلات')}</button>`;$('#confirm-import').onclick=()=>act(async()=>{const r=await api('import',{kind,records:data});m.close();await refresh();render();toast(`${r.added} ${T('added','أُضيف')} · ${r.skipped} ${T('duplicates skipped','مكرر تُخطي')}`)})})}
function generateReport(){const type=$('#report-type').value,owner=$('#report-owner').value,from=$('#report-from').value,to=$('#report-to').value;const match=r=>(!owner||r.owner===owner)&&(!from||r.updated.slice(0,10)>=from)&&(!to||r.updated.slice(0,10)<=to);const list=state.records.filter(match);const heading=T('BD management update','تحديث تطوير الأعمال');reportTitle=type==='suppliers'?T('Supplier screening summary','ملخص فحص الموردين'):type==='meeting'?T('Meeting minutes','محاضر الاجتماعات'):heading;const lines=[`${T('Prepared','أُعد')}: ${day()} · ${T('Owner filter','مرشح المسؤول')}: ${owner||T('All','الكل')}`,`${T('Last-update range','فترة آخر تحديث')}: ${from||T('Any','أي تاريخ')} → ${to||T('Any','أي تاريخ')}`,''];
 if(type==='weekly'){const opp=list.filter(r=>r.kind==='opportunities'),active=opp.filter(r=>!['Won','Lost'].includes(r.stage));lines.push(`${T('ACTIVE OPPORTUNITIES','الفرص النشطة')}: ${active.length}`);const totals={};active.forEach(r=>{if(r.value===''||r.value==null)return;const c=r.currency||'SAR';totals[c]??={value:0,weighted:0,missing:0};totals[c].value+=Number(r.value);if(r.probability!==''&&r.probability!=null)totals[c].weighted+=r.value*r.probability/100;else totals[c].missing++});for(const[c,v]of Object.entries(totals))lines.push(`${c}: ${num(v.value)} ${T('pipeline; weighted','إجمالي؛ مرجح')} ${num(v.weighted)} (${v.missing} ${T('values excluded from weighting: probability missing','قيم مستبعدة من الترجيح لعدم وجود احتمال')})`);lines.push('',T('OPPORTUNITY UPDATES','تحديثات الفرص'));opp.forEach(r=>lines.push(`• ${r.name} | ${r.stage||'—'} | ${T('Owner','المسؤول')}: ${r.owner||'—'} | ${T('Next','التالي')}: ${r.next_action||'—'} | ${r.due||'—'} [${r.id}]`));lines.push('',T('OPEN ACTIONS','الإجراءات المفتوحة'));list.filter(r=>r.kind==='actions'&&r.status!=='Done').forEach(r=>lines.push(`• ${r.name} | ${r.owner||'—'} | ${r.due||'—'}${overdue(r)?' | '+T('OVERDUE','متأخر'):''} [${r.id}]`));lines.push('',T('RISKS / DECISIONS REQUIRED','المخاطر والقرارات المطلوبة'));opp.filter(r=>r.risks).forEach(r=>lines.push(`• ${r.name}: ${r.risks}`));if(!opp.length)lines.push(T('No opportunities match the selected filters.','لا توجد فرص مطابقة للمرشحات.'))}
 if(type==='suppliers'){const s=list.filter(r=>r.kind==='suppliers');lines.push(`${T('Companies','الشركات')}: ${s.length}`,`${T('No presence found / unconfirmed / presence found','لم يُعثر على حضور / غير مؤكد / حضور موجود')}: ${s.filter(r=>r.presence==='no').length} / ${s.filter(r=>r.presence==='maybe').length} / ${s.filter(r=>r.presence==='yes').length}`,'',T('Selected suppliers for follow-up','الموردون بالقائمة المختصرة للمتابعة'));s.filter(r=>r.shortlisted).forEach(r=>lines.push(`• ${r.name} | ${r.group} | ${r.finding}\n${T('Source','المصدر')}: ${r.source_url||T('Not recorded','غير مسجل')}\n${T('Last recheck','آخر إعادة تحقق')}: ${r.verified_date||T('Not reverified','لم يُعد التحقق')}`));lines.push('',T('Imported snapshot dated 9 August 2026; not independently reverified. No presence found is not proof that a territory is available.','بيانات المرجع بتاريخ 9 أغسطس 2026؛ لم يُعد التحقق مستقلاً منها. عدم العثور على حضور لا يثبت توفر التمثيل التجاري.'))}
 if(type==='meeting'){list.filter(r=>r.kind==='meetings').forEach(r=>lines.push(`${r.name} · ${r.date||'—'}`,`${T('Account','الجهة')}: ${name(r.account_id)||'—'}`,`${T('Attendees','الحضور')}: ${r.attendees||'—'}`,`${T('Agenda','الأجندة')}: ${r.agenda||'—'}`,`${T('Decisions','القرارات')}: ${r.decisions||'—'}`,`${T('Follow-up','المتابعة')}: ${r.follow_up||'—'}`,`${T('Notes','الملاحظات')}: ${r.notes||'—'}`,'',`[${r.id}]`,''))}
 lines.push('',T('Prepared from the local workspace. Review before circulation.','أُعد من السجلات المحلية. راجعه قبل تداوله.'));reportText=lines.join('\n');$('#report-title').value=reportTitle;$('#report-text').value=reportText;syncReport();}
function syncReport(){if($('#report-text')){reportText=$('#report-text').value;reportTitle=$('#report-title').value;$('#print-report').textContent=reportText;$('.report-title').textContent=reportTitle}}
function wire(){const on=(s,event,fn)=>{const e=$(s);if(e)e.addEventListener(event,fn)};$$('[data-nav]').forEach(b=>b.onclick=()=>{captureResearch();syncReport();navigate(b.dataset.nav)});$$('[data-new]').forEach(b=>b.onclick=()=>openEditor(b.dataset.new));$$('[data-edit]').forEach(b=>b.onclick=()=>openEditor(get(b.dataset.edit).kind,b.dataset.edit));on('#language','click',()=>{captureResearch();syncReport();lang=lang==='en'?'ar':'en';localStorage.setItem('bd-language',lang);render()});on('#reload','click',()=>act(async()=>{captureResearch();syncReport();await refresh();render()}));on('#search','input',e=>{const pos=e.target.selectionStart;query=e.target.value;page=1;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});$$('[data-filter]').forEach(e=>e.onchange=()=>{filters[e.dataset.filter]=e.value;page=1;render()});on('#clear','click',()=>{query='';filters={};page=1;render()});on('#sort','click',()=>{sortDir*=-1;render()});on('#prev','click',()=>{page--;render()});on('#next','click',()=>{page++;render()});on('#export-table','click',()=>act(async()=>download(await api('export',{kind:route,ids:filtered().map(r=>r.id),columns:columnsFor(route),format:'xlsx'},true),'BD-'+route+'.xlsx')));on('#import-table','click',importTable);$$('[data-complete]').forEach(b=>b.onclick=()=>act(async()=>{const r=get(b.dataset.complete);await api('save',{kind:r.kind,id:r.id,version:r.version,record:{...r,status:'Done'}});await refresh();render()}));$$('[data-source-research]').forEach(b=>b.onclick=()=>{researchDraft.source_ids=[b.dataset.sourceResearch];navigate('research')});on('#research-profile','change',e=>{captureResearch();const p=get(e.target.value);if(p){researchDraft={...researchDraft,profile:p.id,mode:p.mode||'web',source_ids:p.source_ids||[],task_instructions:p.task_instructions||''}}else{researchDraft.task_instructions=templates[e.target.value]||'';researchDraft.source_ids=rows('sources').filter(r=>r.enabled!==false&&r.task===e.target.value).map(r=>r.id)}render()});on('#research-form','input',captureResearch);on('#research-form','change',captureResearch);on('#research-form','submit',e=>{e.preventDefault();captureResearch();if(!state.ai_connected){toast(T('Add your API key in Settings, or copy the full prompt into ChatGPT.','أضف مفتاح API في الإعدادات أو انسخ البرومبت الكامل إلى ChatGPT.'),true);return}busy=true;render();act(async()=>{try{researchResult=await api('research',{...researchDraft,query:researchDraft.query+'\n\n'+T('Answer in English.','أجب بالعربية.')});await refresh()}finally{busy=false;render()}})});on('#copy-prompt','click',()=>copy(fullPrompt()));on('#browser-search','click',()=>{captureResearch();if(!researchDraft.query.trim()){toast(T('Enter a question first.','اكتب السؤال أولاً.'),true);return}const sites=researchDraft.mode==='domains'?rows('sources').filter(r=>researchDraft.source_ids.includes(r.id)&&r.url).map(r=>'site:'+new URL(r.url).hostname).join(' OR '):'';window.open('https://www.google.com/search?q='+encodeURIComponent(researchDraft.query+(sites?' ('+sites+')':'')),'_blank','noopener,noreferrer')});$$('[data-result]').forEach(b=>b.onclick=()=>{captureResearch();researchResult=get(b.dataset.result);render()});on('#research-to-report','click',()=>{captureResearch();reportTitle=researchResult.name;reportText=researchResult.answer+'\n\n'+T('Sources','المصادر')+'\n'+[...new Set((researchResult.blocks||[]).flatMap(b=>b.annotations||[]).map(a=>a.url))].join('\n')+'\n'+(researchResult.source_manifest||[]).map(s=>`[${s.label}] ${s.name} ${s.url||''}`).join('\n');navigate('reports')});on('#generate-report','click',generateReport);on('#report-text','input',syncReport);on('#report-title','input',syncReport);on('#word-report','click',()=>act(async()=>{syncReport();download(await api('report',{title:reportTitle,text:reportText},true),'BD-Report.docx')}));on('#text-report','click',()=>{syncReport();download(new Blob([reportTitle+'\n\n'+reportText],{type:'text/plain;charset=utf-8'}),'BD-Report.txt')});on('#print-report-button','click',()=>{syncReport();window.print()});on('#settings-form','submit',e=>{e.preventDefault();const f=new FormData(e.target),payload={model:f.get('model')};if(f.get('api_key'))payload.api_key=f.get('api_key');act(async()=>{await api('settings',payload);await refresh();render();toast(T('Settings applied for this session.','طُبقت الإعدادات لهذه الجلسة.'))})});on('#disconnect','click',()=>act(async()=>{await api('settings',{api_key:''});await refresh();render()}));on('#backup','click',()=>act(async()=>download(await api('backup',undefined,true),'BD-Workspace-Backup-'+day()+'.zip')));on('#restore','click',()=>pickFile('.zip',async file=>{if(!confirm(T('Merge missing records from this backup? Existing record IDs will be skipped.','دمج السجلات المفقودة من النسخة؟ ستُتخطى معرّفات السجلات الموجودة.')))return;const r=await api('restore',{data:await b64(file)});await refresh();render();toast(`${r.added} ${T('restored','استُعيد')} · ${r.skipped} ${T('already present','موجود مسبقاً')}`)}));}
function registerTools(){if(!document.modelContext?.registerTool)return;const tools=[{name:'search_bd_records',description:'Read locally saved BD records matching text. Does not search the web.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(typeof input?.query!=='string')throw Error('query must be a string');await refresh();return state.records.filter(r=>JSON.stringify(r).toLowerCase().includes(input.query.toLowerCase())).slice(0,30).map(r=>({id:r.id,kind:r.kind,name:r.name,updated:r.updated}))}},{name:'open_research_workspace',description:'Open the research screen and stage a question. Does not send it or start research.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(typeof input?.query!=='string'||input.query.length>16000)throw Error('Invalid query');researchDraft.query=input.query;navigate('research');return {screen:'research',submitted:false}}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}
